private function synchronize(
    ConnectionInterface $connection,
    string $source,
    string $target,
    ?SandboxCopyRules $rules = null,
): void {
    (new SandboxTableSynchronizer($connection))->sync(
        sourceTable: $source,
        targetTable: $target,
        keyColumns: $this->primaryKey,
        columns: [],
        changeColumn: null,
        parentColumn: $this->parentColumn,
        rules: $rules,
    );
}

private function writeSandboxRow(
    Model $model,
    array $keyValues,
    array $attributes,
    array $keyColumns,
): void {
    $query = $model->getConnection()->table($model->getSandboxTable())->where($keyValues);

    if (! $query->exists()) {
        $model->getConnection()->table($model->getSandboxTable())->insert($attributes);

        return;
    }

    $values = $attributes;
    foreach ($keyColumns as $keyColumn) {
        unset($values[$keyColumn]);
    }

    if ($values !== []) {
        $model->getConnection()->table($model->getSandboxTable())->where($keyValues)->update($values);
    }
}

public function sync(
    string $sourceTable,
    string $targetTable,
    array $keyColumns,
    array $columns,
    ?string $changeColumn,
    string $sourceAlias = 'source',
    string $targetAlias = 'target',
    ?string $parentColumn = null,
    ?SandboxCopyRules $rules = null,
): void {
    if ($keyColumns === []) {
        throw new InvalidArgumentException('Sandbox synchronization requires at least one key column.');
    }
    $columns = $columns ?: $this->columnsFrom($sourceTable);
    if ($columns === []) {
        return;
    }
    if ($changeColumn !== null) {
        $this->ensureChangeColumn($sourceTable, $columns, $changeColumn);
    }
    $columns = array_values(array_unique([...$keyColumns, ...$columns]));
    $updateColumns = $rules?->updateColumns ?? $columns;
    if (array_diff($updateColumns, $columns) !== []) {
        throw new InvalidArgumentException('Sandbox update columns must exist in the copied table.');
    }

    $this->connection->transaction(function () use (
        $sourceTable, $targetTable, $keyColumns, $columns, $targetAlias, $sourceAlias, $parentColumn,
        $rules, $updateColumns,
    ): void {
        if ($parentColumn === null) {
            $this->deleteMissing($targetTable, $sourceTable, $keyColumns, $rules);
        }
        if ($parentColumn !== null) {
            $this->insertTreeMissing($targetTable, $sourceTable, $keyColumns, $columns, $parentColumn, $rules);
        }
        if ($updateColumns !== []) {
            $this->updateExisting(
                $targetTable, $sourceTable, $keyColumns,
                array_values(array_unique([...$keyColumns, ...$updateColumns])),
                $targetAlias, $sourceAlias, $rules,
            );
        }
        if ($parentColumn === null) {
            $this->insertMissing($targetTable, $sourceTable, $keyColumns, $columns, $rules);
        } else {
            $this->deleteMissing($targetTable, $sourceTable, $keyColumns, $rules);
        }
    });
}

private function insertTreeMissing(
    string $targetTable,
    string $sourceTable,
    array $keyColumns,
    array $columns,
    string $parentColumn,
    ?SandboxCopyRules $rules,
): void {
    if (count($keyColumns) !== 1 || ! in_array($parentColumn, $columns, true)) {
        throw new InvalidArgumentException('Sandbox tree synchronization requires one key and a selected parent column.');
    }

    $missing = $this->connection->table($sourceTable)
        ->whereNotExists(fn (QueryBuilder $query) => $this->matchingRowSubquery(
            $query, $targetTable, $sourceTable, $keyColumns,
        ));
    if ($rules?->inserts !== null) {
        ($rules->inserts)($missing);
    }

    while ((clone $missing)->exists()) {
        $ready = (clone $missing)->where(function (QueryBuilder $query) use (
            $sourceTable, $targetTable, $parentColumn, $keyColumns,
        ): void {
            $query->whereNull($sourceTable.'.'.$parentColumn)
                ->orWhereColumn($sourceTable.'.'.$parentColumn, $sourceTable.'.'.$keyColumns[0])
                ->orWhereExists(fn (QueryBuilder $parent) => $parent
                    ->select($targetTable.'.'.$keyColumns[0])->from($targetTable)
                    ->whereColumn($targetTable.'.'.$keyColumns[0], $sourceTable.'.'.$parentColumn));
        })->select($columns);

        if ($this->insertChunked($targetTable, $ready->cursor()) === 0) {
            throw new SandboxException('Sandbox tree contains an unresolved parent or a cycle.');
        }
    }
}

private function deleteMissing(
    string $targetTable,
    string $sourceTable,
    array $keyColumns,
    ?SandboxCopyRules $rules,
): void {
    $query = $this->connection->table($targetTable)
        ->whereNotExists(fn (QueryBuilder $query) => $this->matchingRowSubquery(
            $query,
            matchTable: $sourceTable,
            currentTable: $targetTable,
            keyColumns: $keyColumns,
        ));
    if ($rules?->deletes !== null) {
        ($rules->deletes)($query);
    }
    $query->delete();
}

private function updateExisting(
    string $targetTable,
    string $sourceTable,
    array $keyColumns,
    array $columns,
    string $targetAlias,
    string $sourceAlias,
    ?SandboxCopyRules $rules,
): void {
    foreach ($this->matchingRows(
        $targetTable,
        $sourceTable,
        $keyColumns,
        $columns,
        $targetAlias,
        $sourceAlias,
        $rules,
    ) as $row) {
        $attributes = (array) $row;
        $keys = [];
        $values = $attributes;

        foreach ($keyColumns as $keyColumn) {
            $keys[$keyColumn] = $attributes[$keyColumn];
            unset($values[$keyColumn]);
        }

        if ($values !== []) {
            $this->connection->table($targetTable)->where($keys)->update($values);
        }
    }
}

private function matchingRows(
    string $targetTable,
    string $sourceTable,
    array $keyColumns,
    array $columns,
    string $targetAlias,
    string $sourceAlias,
    ?SandboxCopyRules $rules,
): iterable {
    $query = $this->connection->table($sourceTable.' as '.$sourceAlias)
        ->join(
            $targetTable.' as '.$targetAlias,
            fn (JoinClause $join) => $this->joinOnKeys(
                $join,
                $keyColumns,
                $targetAlias,
                $sourceAlias,
            ),
        )
        ->select($this->selectColumns($sourceAlias, $columns));
    if ($rules?->updates !== null) {
        ($rules->updates)($query);
    }

    return $query->cursor();
}

private function joinOnKeys(
    JoinClause $join,
    array $keyColumns,
    string $targetAlias,
    string $sourceAlias,
): void {
    foreach ($keyColumns as $col) {
        $join->on($targetAlias.'.'.$col, '=', $sourceAlias.'.'.$col);
    }
}

private function insertMissing(
    string $targetTable,
    string $sourceTable,
    array $keyColumns,
    array $columns,
    ?SandboxCopyRules $rules,
): void {
    $query = $this->connection->table($sourceTable)
        ->whereNotExists(fn (QueryBuilder $query) => $this->matchingRowSubquery(
            $query,
            matchTable: $targetTable,
            currentTable: $sourceTable,
            keyColumns: $keyColumns,
        ))
        ->select($columns);
    if ($rules?->inserts !== null) {
        ($rules->inserts)($query);
    }

    $this->insertChunked($targetTable, $query->cursor());
}

private function matchingRowSubquery(
    QueryBuilder $query,
    string $matchTable,
    string $currentTable,
    array $keyColumns,
): void {
    $query->select($matchTable.'.'.$keyColumns[0])->from($matchTable);

    $this->whereKeysMatch($query, $matchTable, $currentTable, $keyColumns);
}

private function whereKeysMatch(
    QueryBuilder $query,
    string $leftTable,
    string $rightTable,
    array $keyColumns,
): void {
    foreach ($keyColumns as $col) {
        $query->whereColumn($leftTable.'.'.$col, $rightTable.'.'.$col);
    }
}

trait HasSandbox
{
    protected function newBelongsToMany(
        Builder $query,
        Model $parent,
        mixed $table,
        mixed $foreignPivotKey,
        mixed $relatedPivotKey,
        mixed $parentKey,
        mixed $relatedKey,
        mixed $relationName = null,
    ): BelongsToMany {
        return new SandboxBelongsToMany(
            $query, $parent, $table, $foreignPivotKey, $relatedPivotKey,
            $parentKey, $relatedKey, $relationName,
        );
    }

    /**
     * The suffix appended to active table names for sandbox tables.
     */
    protected static string $sandboxTablePostfix = '_sb';

    /**
     * The primary key used when matching active and sandbox rows.
     *
     * @var string|array<int, string>|null
     */
    protected static string|array|null $sandboxPrimaryKey = null;

    /**
     * The column used to detect changed rows during sync.
     */
    protected static ?string $sandboxTrackChangeColumn = 'change_date';

    /**
     * The columns copied between active and sandbox tables.
     *
     * @var array<int, string>|null
     */
    protected static ?array $sandboxSyncColumns = null;

    /**
     * Get the column used to detect changed rows during sync.
     */
    protected static function getSandboxTrackChangeColumn(): ?string
    {
        if (static::$sandboxTrackChangeColumn === 'change_date' && ! (new static())->timestamps) {
            return null;
        }

        return static::$sandboxTrackChangeColumn;
    }

    /**
     * Indicates if queries should target sandbox data.
     */
    protected static bool $usesSandbox = false;

    private ?string $sandboxActiveTable = null;

    private ?string $sandboxResolvedTable = null;

    private ?bool $sandboxResolvedDraft = null;

    /**
     * Get the active table name for the model.
     */
    public function getActiveTable(): string
    {
        return $this->sandboxActiveTable ??= parent::getTable();
    }

    public function setTable($table): static
    {
        $this->sandboxResolvedDraft = match ($table) {
            $this->getActiveTable()  => false,
            $this->getSandboxTable() => true,
            default                  => $this->isUsingSandboxTable(),
        };
        $this->sandboxResolvedTable = $table;

        return $this;
    }

    /** Preserve the selected layer when Eloquent assigns a self-join alias. */
    public function isUsingSandboxTable(): bool
    {
        return $this->sandboxResolvedDraft ?? static::$usesSandbox;
    }

    /**
     * Get the table associated with the model.
     */
    public function getTable(): string
    {
        return $this->getTableForQuery();
    }

    /**
     * Get the table that should be used for the current query mode.
     */
    public function getTableForQuery(): string
    {
        return $this->sandboxResolvedTable
            ?? (static::$usesSandbox ? $this->getSandboxTable() : $this->getActiveTable());
    }

    /**
     * Get the suffix used for sandbox tables.
     */
    public function getSandboxTablePostfix(): string
    {
        return static::$sandboxTablePostfix;
    }

    /**
     * Get the primary key used to match sandbox rows.
     *
     * @return string|array<int, string>
     */
    public function getSandboxPrimaryKey(): string|array
    {
        return static::$sandboxPrimaryKey ?? $this->getKeyName();
    }

    /**
     * Get the primary key columns as an array.
     *
     * @return array<int, string>
     */
    private function getSandboxPrimaryKeyColumns(): array
    {
        $key = $this->getSandboxPrimaryKey();

        return is_array($key) ? $key : [$key];
    }

    /**
     * Get the sandbox table name for the model.
     */
    public function getSandboxTable(): string
    {
        return $this->getActiveTable().$this->getSandboxTablePostfix();
    }

    /**
     * Switch model queries to sandbox data.
     */
    public static function useSandbox(): void
    {
        static::$usesSandbox = true;
    }

    /**
     * Switch model queries to active data.
     */
    public static function useActive(): void
    {
        static::$usesSandbox = false;
    }

    /**
     * Determine if model queries currently target sandbox data.
     */
    public static function isUsingSandbox(): bool
    {
        return static::$usesSandbox;
    }

    /**
     * Run the callback while model queries target the active table.
     *
     * @template TReturn
     *
     * @param callable(): TReturn $callback
     *
     * @return TReturn
     */
    public static function withoutSandbox(callable $callback): mixed
    {
        return static::usingTableState(false, $callback);
    }

    /**
     * Run the callback while model queries target sandbox data.
     *
     * @template TReturn
     *
     * @param callable(): TReturn $callback
     *
     * @return TReturn
     */
    public static function withSandbox(callable $callback): mixed
    {
        return static::usingTableState(true, $callback);
    }

    /**
     * Scope the query to the sandbox table.
     */
    protected function scopeSandbox(Builder $query): Builder
    {
        $query->getModel()->setTable($this->getSandboxTable());

        return $query->from($this->getSandboxTable());
    }

    /**
     * Scope the query to the active table.
     */
    protected function scopeActive(Builder $query): Builder
    {
        $query->getModel()->setTable($this->getActiveTable());

        return $query->from($this->getActiveTable());
    }

    /**
     * Reset sandbox data from the active table.
     */
    public static function resetSandbox(): void
    {
        $instance = new static();

        static::syncTables(
            sourceTable: $instance->getActiveTable(),
            targetTable: $instance->getSandboxTable(),
            sourceAlias: 't',
            targetAlias: 'sb',
        );
    }

    /**
     * Apply sandbox data to the active table.
     */
    public static function applySandbox(): void
    {
        $instance = new static();

        static::syncTables(
            sourceTable: $instance->getSandboxTable(),
            targetTable: $instance->getActiveTable(),
            sourceAlias: 'sb',
            targetAlias: 't',
        );
    }

    /**
     * Synchronize rows from one configured model table to another.
     */
    private static function syncTables(
        string $sourceTable,
        string $targetTable,
        string $sourceAlias,
        string $targetAlias,
    ): void {
        $instance = new static();

        $instance->getConnection()->transaction(function () use (
            $sourceTable,
            $targetTable,
            $sourceAlias,
            $targetAlias,
            $instance,
        ): void {
            (new SandboxTableSynchronizer($instance->getConnection()))->sync(
                sourceTable: $sourceTable,
                targetTable: $targetTable,
                keyColumns: $instance->getSandboxPrimaryKeyColumns(),
                columns: $instance->getSandboxSyncColumns(),
                changeColumn: static::getSandboxTrackChangeColumn(),
                sourceAlias: $sourceAlias,
                targetAlias: $targetAlias,
            );
        });
    }

    /**
     * Run the callback with a temporary table state.
     *
     * @template TReturn
     *
     * @param callable(): TReturn $callback
     *
     * @return TReturn
     */
    private static function usingTableState(bool $useSandbox, callable $callback): mixed
    {
        $previousState = static::$usesSandbox;
        static::$usesSandbox = $useSandbox;

        try {
            return $callback();
        } finally {
            static::$usesSandbox = $previousState;
        }
    }

    /**
     * Get the columns that may be written during sandbox synchronization.
     *
     * @return array<int, string>
     */
    public function getSandboxWritableColumns(): array
    {
        return $this->getSandboxSyncColumns();
    }

    /**
     * Get the columns copied during sandbox synchronization.
     *
     * @return array<int, string>
     */
    protected function getSandboxSyncColumns(): array
    {
        return static::$sandboxSyncColumns ?? $this->getConnection()->getSchemaBuilder()->getColumnListing($this->getActiveTable());
    }

    /**
     * Determine if the model supports sandbox synchronization.
     */
    public static function supportsSandboxSync(): bool
    {
        return true;
    }
}

class SandboxModelRegistry
{
    /**
     * The models that belong to the sandbox workflow.
     *
     * @var array<int, class-string<Model>>
     */
    private array $models = [];

    /** @var array<string, SandboxTable> */
    private array $tables = [];

    /** @var list<class-string<Model>|SandboxTable> */
    private array $resources = [];

    private ?ConnectionInterface $tableConnection = null;

    public function registerTables(ConnectionInterface $connection, SandboxTable ...$tables): void
    {
        $this->ensureTableConnection($connection);
        foreach ($tables as $table) {
            foreach ($this->tables as $registered) {
                if ($registered == $table) {
                    continue 2;
                }
                if (array_intersect(
                    [$registered->table, $registered->sandboxTable],
                    [$table->table, $table->sandboxTable],
                ) !== []) {
                    throw new InvalidArgumentException('Conflicting sandbox table registration: '.$table->table);
                }
            }
            foreach ($this->models as $model) {
                $this->ensureSeparateTable($model, $table);
            }
            $this->tables[$table->table] = $table;
            $this->resources[] = $table;
            $this->tableConnection = $connection;
        }
    }

    public function ensureTableConnection(ConnectionInterface $connection): void
    {
        throw_if(
            $this->tableConnection !== null && $this->tableConnection !== $connection,
            SandboxException::class,
            'Registered tables must use the sandbox context connection.',
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );
    }

    /** Return null for a table outside the explicitly registered table set. */
    public function resolveTable(string $name, ConnectionInterface $connection, bool $draft): ?string
    {
        foreach ($this->tables as $table) {
            if ($name === $table->table || $name === $table->sandboxTable) {
                $this->ensureTableConnection($connection);

                return $draft ? $table->sandboxTable : $table->table;
            }
        }

        return null;
    }

    private function ensureSeparateTable(string $model, SandboxTable $table): void
    {
        $instance = new $model();
        if (method_exists($instance, 'getActiveTable') && array_intersect(
            [$instance->getActiveTable(), $instance->getSandboxTable()],
            [$table->table, $table->sandboxTable],
        ) !== []) {
            throw new InvalidArgumentException('A sandbox table is already represented by a model: '.$table->table);
        }
    }

    /**
     * The models switched to sandbox data for the current execution context.
     *
     * @var array<int, class-string<Model>>
     */
    private array $switched = [];

    /** @var list<array<class-string<Model>, bool>> */
    private array $contexts = [];

    private ?ConnectionInterface $connection = null;

    public function usingTables(bool $draft, callable $callback, ?ConnectionInterface $connection = null): mixed
    {
        $previousSwitched = $this->switched;
        $previousConnection = $this->connection;
        $this->connection = $connection ?? $previousConnection;
        $this->contexts[] = [];

        try {
            if ($this->connection !== null) {
                $this->ensureTableConnection($this->connection);
            }
            foreach (array_unique([...$this->all(), ...$this->switched]) as $model) {
                $this->ensureConnection($model);
                $this->rememberContext($model);
                $draft ? $model::useSandbox() : $model::useActive();
            }

            return $callback();
        } finally {
            foreach (array_pop($this->contexts) as $model => $previous) {
                $previous ? $model::useSandbox() : $model::useActive();
            }
            $this->switched = $previousSwitched;
            $this->connection = $previousConnection;
        }
    }

    private function rememberContext(string $model): void
    {
        $index = array_key_last($this->contexts);
        if ($index !== null && ! array_key_exists($model, $this->contexts[$index])) {
            $this->contexts[$index][$model] = $model::isUsingSandbox();
        }
    }

    /**
     * Register models that should participate in the sandbox workflow.
     *
     * @param class-string<Model> ...$models
     */
    public function register(string ...$models): void
    {
        foreach ($models as $model) {
            $this->ensureCanUseSandboxTables($model);
            $this->ensureConnection($model);
            $this->ensureCanSync($model);

            foreach ($this->tables as $table) {
                $this->ensureSeparateTable($model, $table);
            }
            if (! in_array($model, $this->models, true)) {
                $this->resources[] = $model;
            }

            $this->remember($this->models, $model);
        }
    }

    /**
     * Get the registered sandbox models.
     *
     * @return array<int, class-string<Model>>
     */
    public function all(): array
    {
        return $this->models;
    }

    /**
     * Switch registered or given models to sandbox data.
     *
     * @param class-string<Model> ...$models
     */
    public function useSandbox(string ...$models): void
    {
        $models = $models === [] ? $this->all() : $models;

        foreach ($models as $model) {
            $this->ensureCanUseSandboxTables($model);
            $this->ensureConnection($model);

            $this->rememberContext($model);
            $this->remember($this->switched, $model);
            $model::useSandbox();
        }
    }

    /**
     * Restore all switched models to active tables.
     */
    public function restoreActiveTables(): void
    {
        foreach ($this->switched as $model) {
            if ($this->canUseSandboxTables($model)) {
                $model::useActive();
            }
        }

        $this->switched = [];
    }

    /**
     * Reset registered sandbox tables from active tables.
     */
    public function resetSandbox(): void
    {
        foreach ($this->resources as $resource) {
            if ($resource instanceof SandboxTable) {
                $resource->resetSandbox($this->tableConnection);
            } else {
                $resource::resetSandbox();
            }
        }
    }

    /**
     * Apply registered sandbox tables to active tables.
     */
    public function applySandbox(): void
    {
        foreach ($this->resources as $resource) {
            if ($resource instanceof SandboxTable) {
                $resource->applySandbox($this->tableConnection);
            } else {
                $resource::applySandbox();
            }
        }
    }

    /**
     * Ensure the model can be switched between active and sandbox tables.
     *
     * @param class-string $model
     *
     * @throws SandboxException
     */
    private function ensureCanUseSandboxTables(string $model): void
    {
        throw_unless(
            $this->canUseSandboxTables($model),
            SandboxException::class,
            sprintf('Model %s must use HasSandbox trait.', $model),
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );
    }

    /**
     * Ensure the model can synchronize sandbox data.
     *
     * @param class-string $model
     *
     * @throws SandboxException
     */
    private function ensureCanSync(string $model): void
    {
        throw_unless(
            is_subclass_of($model, Model::class) && method_exists($model, 'resetSandbox'),
            SandboxException::class,
            sprintf('Model %s has no resetSandbox(). Use HasSandbox trait.', $model),
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );

        throw_unless(
            method_exists($model, 'applySandbox'),
            SandboxException::class,
            sprintf('Model %s has no applySandbox(). Use HasSandbox trait.', $model),
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );
    }

    /**
     * Determine if the model exposes the sandbox table API.
     *
     * @param class-string $model
     */
    private function canUseSandboxTables(string $model): bool
    {
        return class_exists($model)
            && method_exists($model, 'isUsingSandbox')
            && method_exists($model, 'useSandbox')
            && method_exists($model, 'useActive');
    }

    /**
     * Remember a model once while preserving registration order.
     *
     * @param array<int, class-string<Model>> $models
     * @param class-string<Model>             $model
     */
    private function remember(array &$models, string $model): void
    {
        if (! in_array($model, $models, true)) {
            $models[] = $model;
        }
    }

    private function ensureConnection(string $model): void
    {
        if ($this->connection === null) {
            return;
        }

        throw_unless(
            is_subclass_of($model, Model::class) && (new $model())->getConnection() === $this->connection,
            SandboxException::class,
            sprintf('Model %s must use the sandbox context connection.', $model),
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );
    }
}

class EloquentSandboxBackend implements SandboxBackend
{
    public function __construct(
        private readonly SandboxModelRegistry $models,
        private readonly SandboxRecordRestorer $recordRestorer = new SandboxRecordRestorer(),
        private readonly SandboxStatus $statusModel = new SandboxStatus(),
    ) {}

    public function connection(): ConnectionInterface
    {
        return $this->statusModel->getConnection();
    }

    /**
     * Open the sandbox for the given user.
     *
     *
     * @throws SandboxException
     */
    public function open(int|string $userId, bool $force = false, ?string $note = null): void
    {
        $this->ensureRegisteredConnections();
        Log::debug('Opening sandbox', ['user_id' => $userId]);

        $this->connection()->transaction(function () use ($userId, $force, $note): void {
            $status = $this->lockedStatus();

            if (! $force && $status->isLocked() && ! $status->isForUser($userId)) {
                throw new SandboxException(
                    'Sandbox is locked by other user '.$status->user_id,
                    SandboxException::CODE_SANDBOX_LOCKED,
                );
            }

            if ($status->isLockedBy($userId)) {
                return;
            }

            if ($status->isFree()) {
                Event::dispatch(new SandboxResetting());
                $this->initializeDraft();
            } elseif ($force && ! $status->isForUser($userId)) {
                Event::dispatch(new SandboxResetting());
            }

            $this->updateStatusRow($status, [
                'last_operation' => null,
                'status'         => SandboxStatusEnum::Locked,
                'user_id'        => $userId,
                'note'           => $note,
                'change_date'    => now(),
            ]);

            $this->connection()->afterCommit(fn () => Event::dispatch(new SandboxOpened($userId, $force, $note)));

            Log::info('Sandbox opened', ['user_id' => $userId]);
        });
    }

    /** Customize shared-draft preparation while retaining the package's opening lifecycle. */
    protected function initializeDraft(): void
    {
        $this->models->resetSandbox();
    }

    /**
     * Commit the sandbox draft to active data and release the lock.
     *
     * @throws SandboxException
     */
    public function commit(
        int|string $userId,
        ?string $note = null,
    ): void {
        $this->close(
            $userId,
            SandboxOperation::Commit,
            $note,
        );
    }

    /**
     * Roll the sandbox draft back from active data and release the lock.
     *
     * @throws SandboxException
     */
    public function rollback(int|string $userId, ?string $note = null): void
    {
        $this->close($userId, SandboxOperation::Rollback, $note);
    }

    /**
     * Save the sandbox draft without applying it to active data.
     *
     * @throws SandboxException
     */
    public function save(int|string $userId, ?string $note = null): void
    {
        $this->close($userId, SandboxOperation::Save, $note);
    }

    /**
     * Restore active data into the current owner's draft.
     *
     * @param class-string<Model>|Model $modelOrClass
     */
    public function reset(int|string $userId, string|Model $modelOrClass): void
    {
        $this->connection()->transaction(function () use ($userId, $modelOrClass): void {
            $this->ensureLockedBy($this->lockedStatus(), $userId);
            $modelClass = $modelOrClass instanceof Model ? $modelOrClass::class : $modelOrClass;

            throw_unless(
                is_subclass_of($modelClass, Model::class) && method_exists($modelClass, 'resetSandbox'),
                SandboxException::class,
                sprintf('Model %s must extend %s and support resetSandbox().', $modelClass, Model::class),
                SandboxException::CODE_MODEL_NOT_REGISTERED,
            );

            $this->ensureModelConnection($modelOrClass instanceof Model ? $modelOrClass : new $modelClass());

            if ($modelOrClass instanceof Model) {
                $this->recordRestorer->restore($modelOrClass);
            } else {
                $modelClass::resetSandbox();
            }
        });
    }

    private function ensureLockedBy(SandboxStatus $status, int|string $userId): void
    {
        throw_unless(
            $status->isLocked(),
            SandboxException::class,
            'Sandbox must be open before mutation. Use open() first.',
            SandboxException::CODE_SANDBOX_FREE,
        );

        throw_unless(
            $status->isLockedBy($userId),
            SandboxException::class,
            'Sandbox is locked by other user '.$status->user_id,
            SandboxException::CODE_SANDBOX_LOCKED,
        );
    }

    private function ensureRegisteredConnections(): void
    {
        $this->models->ensureTableConnection($this->connection());
        foreach ($this->models->all() as $modelClass) {
            $this->ensureModelConnection(new $modelClass());
        }
    }

    private function ensureModelConnection(Model $model): void
    {
        throw_unless(
            $model->getConnection() === $this->connection(),
            SandboxException::class,
            sprintf('Model %s must use the sandbox status connection.', $model::class),
            SandboxException::CODE_MODEL_NOT_REGISTERED,
        );
    }

    /**
     * Close the sandbox with the given operation.
     *
     * @throws SandboxException
     */
    private function close(
        int|string $userId,
        SandboxOperation $result,
        ?string $note = null,
    ): void {
        $this->ensureRegisteredConnections();
        Log::debug('Closing sandbox', [
            'user_id' => $userId,
            'result'  => $result->label(),
        ]);

        $this->connection()->transaction(function () use ($userId, $result, $note): void {
            $status = $this->lockedStatus();
            $this->ensureLockedBy($status, $userId);

            match ($result) {
                SandboxOperation::Rollback => $this->handleRollback($status, $userId, $note),
                SandboxOperation::Commit   => $this->handleCommit(
                    $status,
                    $userId,
                    $note,
                ),
                SandboxOperation::Save     => $this->handleSave($status, $userId, $note),
            };

            Log::info('Sandbox closed', ['user_id' => $userId, 'result' => $result->label()]);
        });
    }

    /**
     * Roll back the sandbox and release the lock.
     */
    private function handleRollback(SandboxStatus $status, int|string $userId, ?string $note): void
    {
        $closedAt = now();

        Event::dispatch(new SandboxRollingBack());
        Event::dispatch(new SandboxResetting());
        $this->models->resetSandbox();

        $this->updateStatusRow($status, [
            'status'         => SandboxStatusEnum::Free,
            'user_id'        => $userId,
            'last_operation' => SandboxOperation::Rollback,
            'note'           => $note,
            'change_date'    => $closedAt,
            'change_id'      => $status->change_id + 1,
        ]);

        $this->connection()->afterCommit(fn () => Event::dispatch(new SandboxRolledBack(
            $userId,
            $closedAt,
            $note,
        )));
    }

    /**
     * Commit the sandbox and release the lock.
     */
    private function handleCommit(
        SandboxStatus $status,
        int|string $userId,
        ?string $note,
    ): void {
        $closedAt = now();

        Event::dispatch(new SandboxCommitting());
        $this->models->applySandbox();

        $this->updateStatusRow($status, [
            'status'         => SandboxStatusEnum::Free,
            'user_id'        => $userId,
            'last_operation' => SandboxOperation::Commit,
            'note'           => $note,
            'send_date'      => $closedAt,
            'change_date'    => $closedAt,
            'change_id'      => $status->change_id + 1,
        ]);

        $this->connection()->afterCommit(fn () => Event::dispatch(new SandboxCommitted(
            $userId,
            $closedAt,
            $note,
        )));
    }

    /**
     * Save the sandbox without applying it to active data.
     */
    private function handleSave(SandboxStatus $status, int|string $userId, ?string $note): void
    {
        $closedAt = now();

        $this->updateStatusRow($status, [
            'status'         => SandboxStatusEnum::Saved,
            'user_id'        => $userId,
            'last_operation' => SandboxOperation::Save,
            'note'           => $note,
            'change_date'    => $closedAt,
            'change_id'      => $status->change_id + 1,
        ]);

        $this->connection()->afterCommit(fn () => Event::dispatch(new SandboxSaved(
            $userId,
            $closedAt,
            $note,
        )));
    }

    /**
     * Update the singleton sandbox status row.
     *
     * @param array<string, mixed> $attributes
     */
    private function updateStatusRow(SandboxStatus $status, array $attributes): void
    {
        throw_unless(
            $status->forceFill($attributes)->save(),
            SandboxException::class,
            'Sandbox status update was rejected.',
        );

        if ($status->getKeyName() === null) {
            $status->singleton();
        }
    }

    /**
     * Get the locked singleton sandbox status row for a lifecycle mutation.
     */
    private function lockedStatus(): SandboxStatus
    {
        $query = (new SandboxStatusLocker())->query($this->statusModel);

        return $this->statusModel->getKeyName() === null
            ? $this->statusModel->singleton($query)
            : $query->firstOrFail();
    }

    /**
     * Get the current sandbox status row.
     */
    public function status(): ?SandboxStatus
    {
        return $this->statusModel->getKeyName() === null
            ? $this->statusModel->singleton()
            : $this->statusModel->newQuery()->first();
    }
}

class SandboxMiddleware
{
    private readonly SandboxModelRegistry $models;

    private readonly Sandbox $sandbox;

    public function __construct(?SandboxModelRegistry $models = null, ?Sandbox $sandbox = null)
    {
        $this->models = $models ?? app(SandboxModelRegistry::class);
        $this->sandbox = $sandbox ?? app(Sandbox::class);
    }

    public function handle(Request $request, Closure $next): mixed
    {
        $user = $request->user()?->getAuthIdentifier();

        if ($request->isMethodSafe()) {
            return $this->sandbox->read($user, fn (bool $draft) => $this->resolve($request, $next, $draft));
        }

        abort_if($user === null, 403, 'An authenticated user is required to open the sandbox.');

        try {
            return $this->sandbox->edit($user, function () use ($request, $next): mixed {
                $response = $this->resolve($request, $next, true);

                if ($response instanceof Response && $response->getStatusCode() >= 400) {
                    throw new SandboxResponseRejected($response);
                }

                return $response;
            });
        } catch (SandboxResponseRejected $exception) {
            return $exception->response;
        } catch (SandboxException $exception) {
            if ($exception->getCode() !== SandboxException::CODE_SANDBOX_LOCKED) {
                throw $exception;
            }

            throw new HttpException(403, $exception->getMessage(), $exception);
        } catch (ModelNotFoundException $exception) {
            if ($exception->getModel() !== SandboxStatus::class) {
                throw $exception;
            }

            abort(403, 'The sandbox status row is missing.');
        }
    }

    private function resolve(Request $request, Closure $next, bool $draft): mixed
    {
        return $this->models->usingTables($draft, function () use ($request, $next, $draft): mixed {
            if ($draft) {
                $this->models->useSandbox();
                Event::dispatch(new SandboxResolvingModels($request, $this->models));
            }

            return $next($request);
        });
    }

    public function terminate(Request $request, mixed $response): void {}
}

class SandboxServiceProvider extends ServiceProvider
{
    /**
     * Register the package services.
     */
    public function register(): void
    {
        $this->mergeConfigFrom(__DIR__.'/../config/sandbox.php', 'sandbox');

        $this->app->singleton(SandboxModelRegistry::class);
        $this->app->singleton(Contracts\SandboxBackend::class, Backends\EloquentSandboxBackend::class);
        $this->app->singleton(Sandbox::class);
    }

    /**
     * Bootstrap the package services.
     */
    public function boot(): void
    {
        $this->app['router']->aliasMiddleware(
            'sandbox',
            SandboxMiddleware::class,
        );

        Event::listen(SandboxCommitted::class, fn (): mixed => app(SandboxModelRegistry::class)
            ->restoreActiveTables());
        Event::listen(SandboxRolledBack::class, fn (): mixed => app(SandboxModelRegistry::class)
            ->restoreActiveTables());

        Sandbox::macro('for', function (int|string $userId) {
            return new SandboxBuilder($userId);
        });

        Sandbox::macro('me', function () {
            $user = auth()->user();
            if (! $user) {
                throw new \RuntimeException(
                    'No authenticated user found. '
                    .'Use Sandbox::for($userId) instead of Sandbox::me().',
                );
            }

            return new SandboxBuilder($user->getAuthIdentifier());
        });

        if ($this->app->runningInConsole()) {
            $commands = [
                OpenSandboxCommand::class,
                CommitSandboxCommand::class,
                RollbackSandboxCommand::class,
                SaveSandboxCommand::class,
                StatusSandboxCommand::class,
            ];

            if (class_exists(Benchmark::class)) {
                $commands[] = BenchmarkSyncCommand::class;
            }

            $this->commands($commands);

            $this->publishes([
                __DIR__.'/../config/sandbox.php' => config_path('sandbox.php'),
            ], 'sandbox-config');

            $this->publishes([
                __DIR__.'/../database/migrations' => database_path('migrations'),
            ], 'sandbox-migrations');
        }
    }
}
